BEGIN;
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('20260817_013_seed_clasificacion_actividad_pld'));
DO $$ DECLARE n int; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.schema_migrations WHERE migration_key='20260817_012_clasificacion_actividad_pld') THEN RAISE EXCEPTION 'Falta 012'; END IF;
IF EXISTS(SELECT 1 FROM public.schema_migrations WHERE migration_key='20260817_013_seed_clasificacion_actividad_pld') THEN RAISE EXCEPTION '013 ya aplicada'; END IF;
SELECT count(*) INTO n FROM public.usuarios WHERE codigo_principal='PLD_SYSTEM'; IF n<>1 THEN RAISE EXCEPTION 'PLD_SYSTEM no es unico'; END IF;
IF EXISTS(SELECT 1 FROM public.clasificacion_actividad_pld_version WHERE activa AND tipo_catalogo IN ('ACTIVIDAD_ECONOMICA_PF','GIRO_MERCANTIL_PM')) THEN RAISE EXCEPTION 'Version activa previa'; END IF;
END $$;
CREATE TEMP TABLE seed_013(tipo text,clave text,descripcion text,marca text,categoria text) ON COMMIT DROP;
DO $$ BEGIN
IF (SELECT count(*) FROM seed_013)<>99 THEN RAISE EXCEPTION 'Seed interno invalido'; END IF;
IF EXISTS(SELECT 1 FROM seed_013 s LEFT JOIN public.cat_actividades_economicas c ON c.clave::text=s.clave WHERE s.tipo='ACTIVIDAD_ECONOMICA_PF' AND c.clave IS NULL) OR EXISTS(SELECT 1 FROM seed_013 s LEFT JOIN public.cat_giros_mercantiles c ON c.clave::text=s.clave WHERE s.tipo='GIRO_MERCANTIL_PM' AND c.clave IS NULL) THEN RAISE EXCEPTION 'Clave maestra faltante'; END IF;
END $$;
SELECT * FROM (VALUES ('ACTIVIDAD_ECONOMICA_PF','PLD_VISSION_ACTIVIDAD_ECONOMICA_PF','Actividad economica PF.xlsx','20260817_INICIAL',NULL::date,DATE '2026-08-17',true),('GIRO_MERCANTIL_PM','PLD_VISSION_GIRO_MERCANTIL_PM','Giro mercantil PM.xlsx','20260817_INICIAL',NULL::date,DATE '2026-08-17',true)) v CROSS JOIN LATERAL(SELECT id FROM public.usuarios WHERE codigo_principal='PLD_SYSTEM')u;
